blocks.crop_admission:
def _crop_pools(v, seeds_left, day):
    free = [q for q in sorted(v["empty"], key=lambda q: (_shed_dist(q), q)) if q not in S["claimed_sites"]]
    n_rec = seeds_left.get("STRAWBERRY", 0) + seeds_left.get("TOMATO", 0)
    n_one = sum(seeds_left.get(c, 0) for c in CROP_SPECS) - n_rec
    if n_one < 0:
        n_one = 0
    near = [q for q in free if _shed_dist(q) <= NEAR_RADIUS]
    far_left = [q for q in free if _shed_dist(q) > NEAR_RADIUS]
    rec_sites = near[:n_rec]
    near_left = near[n_rec:]
    if len(rec_sites) < n_rec:
        take = n_rec - len(rec_sites)
        rec_sites = rec_sites + far_left[:take]
        far_left = far_left[take:]
    one_sites = far_left[:n_one]
    if len(one_sites) < n_one:
        one_sites = one_sites + near_left[:n_one - len(one_sites)]
    plant = rec_sites + one_sites
    return {"urgent": list(v["urgent"]), "wwater": list(v["wwater"]), "harvest": list(v["harvest"]), "water": list(v["water"]),
            "fert": list(v["fert"]), "plant": plant, "weeds": list(v["weeds"]), "slack": list(v["slack"])}


def _plant_choice(pos, seeds_left):
    d = _shed_dist(pos)
    if d <= NEAR_RADIUS:
        order = ["STRAWBERRY", "TOMATO", "MELON", "CARROT", "WHEAT"]
    elif d <= NEAR_RADIUS + 3:
        order = ["MELON", "CARROT", "WHEAT", "STRAWBERRY", "TOMATO"]
    else:
        order = ["WHEAT", "MELON", "CARROT", "TOMATO", "STRAWBERRY"]
    for c in order:
        if seeds_left.get(c, 0) > 0:
            return c
    return None


def _task_valid(tp, kind, v, day, hour, carry, seeds_left):
    t = v["tiles"][tp[1]][tp[0]]
    if kind in ("urgent", "water", "slack", "wwater"):
        return isinstance(t, dict) and t.get("kind") == "PLANT" and not t.get("watered_today")
    if kind == "harvest":
        return isinstance(t, dict) and t.get("kind") == "PLANT" and t.get("yield_units", 0) > 0
    if kind == "fert":
        return carry.get("FERTILIZER", 0) > 0 and isinstance(t, dict) and _fert_eligible(t, day)
    if kind == "plant":
        return t is None and _plant_choice(tp, seeds_left) is not None and hour < 22
    if kind == "weeds":
        return isinstance(t, dict) and t.get("kind") == "WEED"
    return False

blocks.animal_routing:
def _build_route(i, pos, v, day, shed, carry, unlocked_shed, hour=0):
    claimed = set()
    for r in S["routes"].values():
        claimed.update(r["stops"])
    cands = [(p2, t) for p2, t in v["animals"] if p2 not in claimed and _animal_pending(t, day)]
    if not cands and hour >= 14:
        best = None
        for j, r in S["routes"].items():
            if j == i or len(r["stops"]) < 2:
                continue
            tp = r["stops"][-1]
            t = v["tiles"][tp[1]][tp[0]]
            needs_wheat = day < 29 and not t.get("fed_today", False) and carry.get("WHEAT", 0) == 0
            if needs_wheat:
                continue
            gain = _dist(v["positions"][j], tp) - _dist(pos, tp)
            if gain >= 3 and (best is None or gain > best[0]):
                best = (gain, j)
        if best is not None:
            tp = S["routes"][best[1]]["stops"].pop()
            cands = [(tp, v["tiles"][tp[1]][tp[0]])]
    if not cands:
        return None
    # C: route length scales with herd size instead of a fixed constant, so a bigger
    # fleet gets longer batched routes per hand rather than more, shorter ones.
    herd = len(v["animals"])
    route_len = min(5, max(2, herd // 3))
    # unfed animals go first in the stop order so a hand never reaches a cared-but-unfed
    # animal only to have to double back for wheat.
    unfed_pool = {}
    fed_pool = {}
    for p2, t in cands:
        if day < 29 and not t.get("fed_today", False):
            unfed_pool[p2] = t
        else:
            fed_pool[p2] = t
    stops = []
    cur = pos
    while unfed_pool and len(stops) < route_len:
        nxt = _nearest(cur, list(unfed_pool.keys()))
        stops.append(nxt)
        cur = nxt
        del unfed_pool[nxt]
    while fed_pool and len(stops) < route_len:
        nxt = _nearest(cur, list(fed_pool.keys()))
        stops.append(nxt)
        cur = nxt
        del fed_pool[nxt]
    unfed = sum(1 for s_ in stops if not v["tiles"][s_[1]][s_[0]].get("fed_today", False)) if day < 29 else 0
    need = max(0, unfed - carry.get("WHEAT", 0))
    pickup = min(need, S["wheat_budget"]) if unlocked_shed else 0
    S["wheat_budget"] -= pickup
    return {"stops": stops, "pickup": pickup}


def _route_step(i, pos, v, day, hour, shed, carry, unlocked_shed):
    # feed/care are already paired in the same visit, and fertilizer is only collected
    # while standing on the tile (both verified unchanged from the chassis below).
    r = S["routes"][i]
    tiles = v["tiles"]
    if r["pickup"] > 0:
        if pos in unlocked_shed:
            n = min(r["pickup"], shed.get("WHEAT", 0))
            r["pickup"] = 0
            if n > 0:
                return ["PICKUP", "WHEAT", int(n)]
            if hour <= 1:
                r["pickup"] = 1
                return ["PASS"]
        else:
            return [_step(pos, _nearest(pos, unlocked_shed))]
    while r["stops"]:
        tgt = r["stops"][0]
        t = tiles[tgt[1]][tgt[0]]
        if not (isinstance(t, dict) and "animal" in t):
            r["stops"].pop(0)
            continue
        if pos != tgt:
            return [_step(pos, tgt)]
        if day < 29 and not t.get("fed_today", False) and carry.get("WHEAT", 0) > 0:
            return ["FEED"]
        if day < 29 and not t.get("fed_today", False) and carry.get("WHEAT", 0) == 0 and S["wheat_budget"] > 0 and hour < 21 and not r.get("refilled"):
            unfed = sum(1 for s_ in r["stops"] if not tiles[s_[1]][s_[0]].get("fed_today", False))
            r["pickup"] = min(unfed, S["wheat_budget"]); S["wheat_budget"] -= r["pickup"]; r["refilled"] = True
            return [_step(pos, _nearest(pos, unlocked_shed))] if pos not in unlocked_shed else ["PICKUP", "WHEAT", int(r["pickup"])]
        if day < 28 and not t.get("cared_today", False):
            return ["CARE"]
        if t.get("fertilizer_available", False):
            return ["COLLECT_FERTILIZER"]
        if t.get("yield_units", 0) > 0:
            return ["HARVEST"]
        r["stops"].pop(0)
    del S["routes"][i]
    return None
